const updateVideoSourceStatus = `-- name: UpdateVideoSourceStatus :one
UPDATE video_sources
SET status = $1, updated_at = now()
WHERE id = $2
RETURNING id, author_user_id, source_type, source_url, external_id, title, description, category, thumbnail_url, thumbnail_media_id, duration_secs, status, field_values, created_at, updated_at, source_id, slug
`

type UpdateVideoSourceStatusParams struct {
	Status string      `json:"status"`
	ID     pgtype.UUID `json:"id"`
}

// Used by the takedown approval flow to hide a specific video.
func (q *Queries) UpdateVideoSourceStatus(ctx context.Context, arg UpdateVideoSourceStatusParams) (VideoSource, error) {
	row := q.db.QueryRow(ctx, updateVideoSourceStatus, arg.Status, arg.ID)
	var i VideoSource
	err := row.Scan(
		&i.ID,
		&i.AuthorUserID,
		&i.SourceType,
		&i.SourceUrl,
		&i.ExternalID,
		&i.Title,
		&i.Description,
		&i.Category,
		&i.ThumbnailUrl,
		&i.ThumbnailMediaID,
		&i.DurationSecs,
		&i.Status,
		&i.FieldValues,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SourceID,
		&i.Slug,
	)
	return i, err
}
